/**
 * UC2-MIRROR tests — the opencode forensics module (`src/uc2-forensics.ts`)
 * mirrors hermes `UC2Forensics` (packages/hermes/src/uc2_forensics.py) and is
 * pinned to the same behaviors:
 *
 *   - wrapper result shape {exit_code, report, stderr} + exact arg assembly;
 *   - binary-not-found law (exit 2 + the hermes stderr prose);
 *   - the full verdict decomposition over stub binaries (all three verdict
 *     classes, reason strings identical to hermes);
 *   - golden parity against the shared fixture
 *     `fixtures/uc2-diagnose-golden.json` (generated by the hermes reference on
 *     real corpus anchors) — real binaries required, same anchors both sides
 *     (09-plugin-parity.md §4; hermes mirror test lives in
 *     packages/hermes/test/test_uc2_forensics.py, added in the same card).
 *
 * Run: node --test test/ (from packages/opencode).
 */

import assert from "node:assert/strict";
import { test } from "node:test";
import { chmodSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

import { UC2_FEATURE, UC2Forensics, rustBinDir } from "../src/uc2-forensics.ts";

const REPO_ROOT = fileURLToPath(new URL("../../../", import.meta.url));

const STUB_REPLAY = `#!/bin/sh
echo "args: $*" >&2
if [ "\${STUB_REPLAY_MODE:-}" = "divergence" ]; then
  echo '{"divergences": [{"expectedHash": "sha256:stub", "actualHash": "sha256:nope"}]}'
else
  echo '{"divergences": []}'
fi
exit 0
`;

const STUB_PROFILE = `#!/bin/sh
echo "args: $*" >&2
event=""
prev=""
for a in "$@"; do
  if [ "$prev" = "--event" ]; then event="$a"; fi
  prev="$a"
done
if [ "$event" = "page.fault" ]; then
  if [ -n "\${STUB_NOFAULT:-}" ]; then
    echo '{"events": 0, "faults": []}'
  else
    echo '{"events": 2, "faults": [{"page": {"contentHash": "sha256:stub0001", "logicalRef": "doc:a"}, "source": "identifier_scan", "turn": 3}, {"page": {"contentHash": "sha256:stub0002", "logicalRef": "doc:b"}, "source": "tool_recall", "turn": 3}]}'
  fi
elif [ "$event" = "page.evict" ]; then
  if [ -n "\${STUB_NOEVICT:-}" ]; then
    echo '{"events": 0, "evictions": []}'
  else
    echo '{"events": 1, "evictions": [{"page": {"contentHash": "sha256:stub0003", "logicalRef": "doc:a"}, "stubText": "[Paged out: doc:a]", "turn": 1}]}'
  fi
else
  echo '{"events": 0}'
fi
exit 0
`;

const STUB_DIFF = `#!/bin/sh
echo "args: $*" >&2
echo '{"relations": ["a_extends_b"], "sharedPrefix": true}'
exit 0
`;

const STUB_EXPORT = `#!/bin/sh
echo "args: $*" >&2
echo '{"artifacts": [], "odps": true, "snapshot": {"keptEvents": 20, "droppedEvents": 2}}'
exit 0
`;

/** Create a temp dir holding the four stub binaries; caller removes it. */
function stubBinDir(): string {
  const dir = mkdtempSync(join(tmpdir(), "uc2-stub-"));
  const write = (name: string, body: string): void => {
    const path = join(dir, name);
    writeFileSync(path, body);
    chmodSync(path, 0o755);
  };
  write("replay", STUB_REPLAY);
  write("profile", STUB_PROFILE);
  write("diff", STUB_DIFF);
  write("export", STUB_EXPORT);
  return dir;
}

function withEnv(variables: Record<string, string | undefined>, fn: () => void): void {
  const saved: Record<string, string | undefined> = {};
  for (const [key, value] of Object.entries(variables)) {
    saved[key] = process.env[key];
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
  }
  try {
    fn();
  } finally {
    for (const [key, value] of Object.entries(saved)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  }
}

test("uc2 module mirrors the hermes registry identity (name/feature/enabled)", () => {
  assert.equal(UC2_FEATURE, "uc2-forensics");
  const uc2 = new UC2Forensics();
  assert.equal(uc2.name, "uc2-forensics");
  assert.equal(uc2.feature, "uc2-forensics");
  assert.ok(uc2.enabled(new Set(["uc2-forensics"])));
  assert.ok(!uc2.enabled(new Set(["trace"])));
  assert.ok(!uc2.enabled(new Set()));
});

test("replay wrapper: shape, exit code, and hermes arg assembly", () => {
  const dir = stubBinDir();
  try {
    withEnv({ CTXVM_RUST_BIN_DIR: dir }, () => {
      const result = new UC2Forensics().replay("/tmp/trace.jsonl", {
        turn: 3,
        pins: ["sha256:abc"],
        output: "/tmp/rep.json",
      });
      assert.deepEqual(Object.keys(result), ["exit_code", "report", "stderr"]);
      assert.equal(result.exit_code, 0);
      assert.deepEqual((result.report as Record<string, unknown>).divergences, []);
      assert.equal(result.stderr, "args: /tmp/trace.jsonl --turn 3 --pin sha256:abc --output /tmp/rep.json\n");
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

