test("binary not found: exit 2 + the hermes stderr prose (exact)", () => {
  const emptyDir = mkdtempSync(join(tmpdir(), "uc2-empty-"));
  try {
    withEnv({ CTXVM_RUST_BIN_DIR: emptyDir }, () => {
      assert.equal(rustBinDir(), resolve(emptyDir));
      const result = new UC2Forensics().replay("/tmp/trace.jsonl");
      assert.equal(result.exit_code, 2);
      assert.equal(result.report, "");
      assert.equal(
        result.stderr,
        "binary not found: replay (set CTXVM_RUST_BIN_DIR or add rust/target/release to PATH)",
      );
    });
  } finally {
    rmSync(emptyDir, { recursive: true, force: true });
  }
});

test("diagnose (stub): context-management verdict + reason string parity", () => {
  const dir = stubBinDir();
  try {
    withEnv({ CTXVM_RUST_BIN_DIR: dir }, () => {
      const result = new UC2Forensics().diagnose("/tmp/trace.jsonl", 3);
      assert.equal(result.fault_turn, 3);
      assert.equal(result.verdict, "context-management");
      assert.equal(result.reason, "page evicted before fault turn — pager dropped needed content");
      assert.deepEqual(Object.keys(result.evidence), [
        "faults_at_turn",
        "evictions_before",
        "replay_exit_code",
        "replay_divergences",
      ]);
      assert.equal(result.evidence.faults_at_turn.length, 2);
      assert.equal(result.evidence.evictions_before.length, 1);
      assert.equal(result.evidence.replay_exit_code, 0);
      assert.deepEqual(result.evidence.replay_divergences, []);
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("diagnose (stub): model-reasoning verdict + reason string parity", () => {
  const dir = stubBinDir();
  try {
    withEnv({ CTXVM_RUST_BIN_DIR: dir, STUB_NOEVICT: "1" }, () => {
      const result = new UC2Forensics().diagnose("/tmp/trace.jsonl", 3);
      assert.equal(result.verdict, "model-reasoning");
      assert.equal(result.reason, "page resident at fault turn — pager not at fault");
      assert.equal(result.evidence.evictions_before.length, 0);
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

