test("diagnose (stub): inconclusive when the replay fact gate is dirty", () => {
  const dir = stubBinDir();
  try {
    withEnv({ CTXVM_RUST_BIN_DIR: dir, STUB_REPLAY_MODE: "divergence" }, () => {
      const result = new UC2Forensics().diagnose("/tmp/trace.jsonl", 3);
      assert.equal(result.verdict, "inconclusive");
      assert.equal(
        result.reason,
        "replay at turn 3 not divergence-free (exit 0)",
      );
      assert.equal(result.evidence.replay_divergences.length, 1);
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("golden parity: diagnose matches the hermes-generated fixture on every anchor", () => {
  assert.ok(rustBinDir() !== null, "rust release binaries missing — run `cargo build --release` (the golden parity test is normative, not skippable)");
  const fixture = JSON.parse(
    readFileSync(fileURLToPath(new URL("./fixtures/uc2-diagnose-golden.json", import.meta.url)), "utf8"),
  ) as {
    meta: { generatedBy: string };
    anchors: Array<{ trace: string; faultTurn: number; expectedVerdict: string; diagnose: object }>;
  };
  assert.ok(
    fixture.meta.generatedBy.includes("packages/hermes/src/uc2_forensics.py"),
    "fixture must be generated by the hermes reference implementation",
  );
  const uc2 = new UC2Forensics();
  for (const anchor of fixture.anchors) {
    const got = uc2.diagnose(join(REPO_ROOT, anchor.trace), anchor.faultTurn);
    assert.equal(got.verdict, anchor.expectedVerdict);
    assert.deepStrictEqual(
      got,
      anchor.diagnose,
      `golden drift at ${anchor.trace} turn ${anchor.faultTurn}`,
    );
  }
});

test("kit entry: tools/uc2-forensics.sh diagnose prints the module verdict (real corpus)", () => {
  assert.ok(rustBinDir() !== null, "rust release binaries missing — run `cargo build --release`");
  const stdout = execFileSync(
    join(REPO_ROOT, "tools", "uc2-forensics.sh"),
    ["diagnose", "corpus/m2/live-thrash.jsonl", "0"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  const verdict = JSON.parse(stdout) as { verdict: string; fault_turn: number };
  assert.equal(verdict.fault_turn, 0);
  assert.equal(verdict.verdict, "model-reasoning");
});
